import React, { useState } from "react";
import ChatWindow from "./components/ChatWindow";
import ChatInput from "./components/ChatInput";
import AdminDashboard from "./components/AdminDashboard";
import { sendMessage } from "./services/api";

function App() {
  const [messages, setMessages] = useState([]);
  const [isAdmin, setIsAdmin] = useState(false); // 🔥 ADD THIS

  const handleSend = async (text) => {
    const newMessages = [...messages, { sender: "You", text }];
    setMessages(newMessages);

    try {
      const res = await sendMessage(text);

      setMessages([
        ...newMessages,
        { sender: "Bot", text: res.data.answer }
      ]);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={{ width: "400px", margin: "auto", marginTop: "50px" }}>

      {/* 🔥 TOGGLE BUTTON */}
      <button onClick={() => setIsAdmin(!isAdmin)}>
        {isAdmin ? "Go to Chat" : "Go to Admin"}
      </button>

      <h2>EduSaarthi Chat 🤖</h2>

      {isAdmin ? (
        <AdminDashboard />   // ✅ ADMIN SHOW
      ) : (
        <>
          <ChatWindow messages={messages} />
          <ChatInput onSend={handleSend} />
        </>
      )}
    </div>
  );
}

export default App;
